package com.nigson.integration.notification;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import io.micrometer.core.instrument.MeterRegistry;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.integration.providers.TwilioAccount;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import tools.jackson.databind.JsonNode;

/** Paired owner-local staff reply leases and single-write checkpoint. */
public final class StaffReplyExecution {
 public record Claim(UUID id,UUID lead,UUID correlation,String destinationHash,String accountHash,String contextRevision,String contextBasis,byte[] recipientCiphertext,byte[] variablesCiphertext,long jobVersion,long dispatchVersion,Instant lease,boolean compatible,boolean maySend,String sid,JsonNode template){public Claim{recipientCiphertext=recipientCiphertext.clone();variablesCiphertext=variablesCiphertext.clone();template=template.deepCopy();}@Override public byte[] recipientCiphertext(){return recipientCiphertext.clone();}@Override public byte[] variablesCiphertext(){return variablesCiphertext.clone();}@Override public JsonNode template(){return template.deepCopy();}@Override public String toString(){return "StaffReplyClaim[protected]";}}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AuditWriter audit;private final Clock clock;private final ProviderHttp.Mode transport;private final String mode,accountHash;private final UUID generation;private final Instant notBefore;private final MeterRegistry metrics;
 public StaffReplyExecution(JdbcTemplate jdbc,PlatformTransactionManager manager,AuditWriter audit,Clock clock,ProviderHttp.Mode mode,String accountHash,UUID generation,Instant notBefore,MeterRegistry metrics){if(mode==null||accountHash==null||!accountHash.matches("[a-f0-9]{64}")||generation==null||generation.equals(new UUID(0,0))||notBefore==null)throw new IllegalArgumentException("STAFF_REPLY_EXECUTION_IDENTITY_REQUIRED");this.jdbc=Objects.requireNonNull(jdbc);tx=new TransactionTemplate(manager);tx.setTimeout(5);this.audit=Objects.requireNonNull(audit);this.clock=Objects.requireNonNull(clock);transport=mode;this.mode=mode==ProviderHttp.Mode.TEST?"SANDBOX":mode.name();this.accountHash=accountHash;this.generation=generation;this.notBefore=notBefore;this.metrics=Objects.requireNonNull(metrics);}
 private Timestamp now(){return Timestamp.from(clock.instant());}private void local(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private static long ver(Map<String,Object> row){return ((Number)row.get("version")).longValue();}private static int attempts(Map<String,Object> row){return ((Number)row.get("attempt_count")).intValue();}
 private boolean identity(Map<String,Object> j,Map<String,Object> d){try{var t=EventCodec.JSON.readTree(d.get("template_snapshot").toString());return "experience".equals(j.get("owner_service"))&&"STAFF_LEAD_REPLY".equals(j.get("template_code"))&&"TRANSACTIONAL".equals(j.get("classification"))&&"WHATSAPP".equals(j.get("channel"))&&"STAFF_LEAD_REPLY".equals(t.path("code").asString())&&"TRANSACTIONAL".equals(t.path("classification").asString())&&"WHATSAPP".equals(t.path("channel").asString())&&t.isObject()&&t.propertyNames().equals(Set.of("id","code","revision","locale","channel","classification","body","providerTemplateId","variablesSchema"))&&d.get("template_hash").equals(EventCodec.hash(t))&&t.path("id").asString().equals(d.get("template_id").toString())&&t.path("locale").asString().equals(d.get("locale"))&&t.path("revision").asInt()==((Number)j.get("template_revision")).intValue()&&t.path("providerTemplateId").asString().matches("HX[a-fA-F0-9]{32}")&&accountHash.equals(d.get("account_hash"))&&accountHash.equals(TwilioAccount.fingerprint(transport,(String)d.get("account_sid"),(String)d.get("messaging_service_sid")))&&mode.equals(j.get("provider_mode"))&&Objects.equals(j.get("provider_reference"),d.get("provider_message_id"))&&d.get("command_hash")!=null&&((String)d.get("command_hash")).matches("[a-f0-9]{64}")&&d.get("recipient_ciphertext") instanceof byte[]&&((byte[])d.get("recipient_ciphertext")).length>=29&&d.get("variables_ciphertext") instanceof byte[]&&((byte[])d.get("variables_ciphertext")).length>=29&&Set.of("SIGNED_INBOUND_REQUEST","VERIFIED_DESTINATION").contains(d.get("context_basis"));}catch(RuntimeException invalid){return false;}}
 private boolean fresh(Map<String,Object> j,Map<String,Object> d){Timestamp occurred=(Timestamp)d.get("source_occurred_at");return identity(j,d)&&"INTENT".equals(d.get("stage"))&&attempts(j)==0&&attempts(d)==0&&d.get("submitted_at")==null&&d.get("request_hash")==null&&d.get("provider_message_id")==null&&generation.equals(d.get("generation"))&&!occurred.toInstant().isBefore(notBefore)&&!occurred.toInstant().isAfter(clock.instant().plusSeconds(30));}
 private Claim claim(Map<String,Object> j,Map<String,Object> d,boolean compatible,boolean may){return new Claim((UUID)j.get("id"),(UUID)j.get("resource_id"),(UUID)d.get("correlation_id"),(String)j.get("destination_hash"),(String)d.get("account_hash"),(String)d.get("context_key_revision"),(String)d.get("context_basis"),(byte[])d.get("recipient_ciphertext"),(byte[])d.get("variables_ciphertext"),ver(j),ver(d),((Timestamp)d.get("lease_until")).toInstant(),compatible,may,(String)d.get("provider_message_id"),EventCodec.JSON.readTree(d.get("template_snapshot").toString()));}
 public Optional<Claim> claim(){return tx.execute(status->{local();var jobs=jdbc.queryForList("SELECT * FROM integration.notification_job WHERE owner_service='experience' AND template_code='STAFF_LEAD_REPLY' AND classification='TRANSACTIONAL' AND channel='WHATSAPP' AND state IN ('PENDING','CLAIMED','SENT','UNKNOWN') AND next_attempt_at<=? AND (lease_until IS NULL OR lease_until<=?) ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED",now(),now());if(jobs.isEmpty())return Optional.empty();var j=jobs.getFirst();UUID id=(UUID)j.get("id");var ds=jdbc.queryForList("SELECT * FROM integration.notification_dispatch WHERE id=? FOR UPDATE",id);if(ds.size()!=1){unknownMissing(j);return Optional.empty();}var d=ds.getFirst();if(d.get("lease_until")!=null&&((Timestamp)d.get("lease_until")).toInstant().isAfter(clock.instant()))return Optional.empty();boolean valid=identity(j,d),may="PENDING".equals(j.get("state"))&&j.get("lease_until")==null&&d.get("lease_until")==null&&fresh(j,d);Instant lease=clock.instant().plusSeconds(60);jdbc.update("UPDATE integration.notification_job SET state='CLAIMED',lease_until=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",Timestamp.from(lease),now(),id);jdbc.update("UPDATE integration.notification_dispatch SET lease_until=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",Timestamp.from(lease),now(),id);evidence(id,(UUID)d.get("correlation_id"),"CLAIMED");return Optional.of(claim(jdbc.queryForMap("SELECT * FROM integration.notification_job WHERE id=?",id),jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",id),valid,may));});}
 private void unknownMissing(Map<String,Object> j){UUID id=(UUID)j.get("id");jdbc.update("UPDATE integration.notification_job SET state='UNKNOWN',lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",Timestamp.from(clock.instant().plusSeconds(300)),now(),id);audit.append("staff-reply-worker",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.NOTIFICATION,id,UUID.nameUUIDFromBytes(("staff-missing:"+id).getBytes(java.nio.charset.StandardCharsets.US_ASCII)),AuditValues.Reason.RECONCILIATION,null,Map.of("state","UNKNOWN"),null);}
 private List<Map<String,Object>> lock(Claim c){local();var jobs=jdbc.queryForList("SELECT * FROM integration.notification_job WHERE id=? FOR UPDATE",c.id());var ds=jdbc.queryForList("SELECT * FROM integration.notification_dispatch WHERE id=? FOR UPDATE",c.id());if(jobs.size()!=1||ds.size()!=1)return List.of();var j=jobs.getFirst();var d=ds.getFirst();if(ver(j)!=c.jobVersion()||ver(d)!=c.dispatchVersion()||!"CLAIMED".equals(j.get("state"))||j.get("lease_until")==null||d.get("lease_until")==null||!((Timestamp)j.get("lease_until")).toInstant().equals(c.lease())||!((Timestamp)d.get("lease_until")).toInstant().equals(c.lease())||!c.lease().isAfter(clock.instant()))return List.of();return List.of(j,d);}
 public Optional<Claim> prepare(Claim c,String requestHash){if(!c.compatible()||!c.maySend()||requestHash==null||!requestHash.matches("[a-f0-9]{64}"))throw rule();return tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return Optional.empty();var j=rows.get(0);var d=rows.get(1);if(!fresh(j,d))throw rule();var template=EventCodec.JSON.readTree(d.get("template_snapshot").toString());var active=jdbc.queryForList("SELECT code,revision,locale,channel,classification,body,provider_template_id,variables_schema::text FROM integration.notification_template WHERE id=? AND active FOR SHARE",d.get("template_id"));if(active.size()!=1)throw rule();var t=active.getFirst();if(!"STAFF_LEAD_REPLY".equals(t.get("code"))||!"TRANSACTIONAL".equals(t.get("classification"))||!"WHATSAPP".equals(t.get("channel"))||!Objects.equals(t.get("locale"),d.get("locale"))||!Objects.equals(t.get("revision"),j.get("template_revision"))||!Objects.equals(t.get("body"),template.path("body").asString())||!Objects.equals(t.get("provider_template_id"),template.path("providerTemplateId").asString())||!EventCodec.JSON.readTree(t.get("variables_schema").toString()).equals(template.path("variablesSchema")))throw rule();jdbc.update("UPDATE integration.notification_job SET attempt_count=1,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",now(),c.id());jdbc.update("UPDATE integration.notification_dispatch SET stage='SUBMITTING',attempt_count=1,submitted_at=?,request_hash=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",now(),requestHash,now(),c.id());evidence(c.id(),c.correlation(),"SUBMITTING");return Optional.of(claim(jdbc.queryForMap("SELECT * FROM integration.notification_job WHERE id=?",c.id()),jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",c.id()),true,false));});}
 public boolean suppressed(Claim c){return finishPrewrite(c,"SUPPRESSED","SUPPRESSED","CONSENT_RULE_VIOLATION");}
 public boolean unknown(Claim c,String reason){if(!Set.of("PROVIDER_OUTCOME_UNKNOWN","PROVIDER_MODE_MISMATCH").contains(reason))throw rule();return finishPrewrite(c,"UNKNOWN","UNKNOWN",reason);}
 private boolean finishPrewrite(Claim c,String state,String stage,String error){return Boolean.TRUE.equals(tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return false;var j=rows.get(0);var d=rows.get(1);jdbc.update("UPDATE integration.notification_job SET state=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",state,Timestamp.from(clock.instant().plusSeconds(300)),now(),c.id());jdbc.update("UPDATE integration.notification_dispatch SET stage=?,error_code=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",stage,error,Timestamp.from(clock.instant().plusSeconds(300)),now(),c.id());if(attempts(d)>0)jdbc.update("INSERT INTO integration.notification_attempt(id,created_by,job_id,attempt_number,provider,result,error_code,duration_ms,channel) VALUES (?,'staff-reply-worker',?,1,'TWILIO',?,?,0,'WHATSAPP') ON CONFLICT (job_id,attempt_number) DO NOTHING",EventCodec.uuid7(clock.instant()),c.id(),state,error);evidence(c.id(),c.correlation(),state);return true;}));}
 public boolean outcome(Claim c,JsonNode response,int duration){if(response==null||duration<0)throw rule();String sid=response.path("sid").asString(),status=response.path("status").asString();if(!sid.matches("SM[a-fA-F0-9]{32}")||!Set.of("accepted","scheduled","queued","sending","sent","delivered","read","failed","undelivered","canceled").contains(status)||c.sid()!=null&&!c.sid().equals(sid))throw rule();return Boolean.TRUE.equals(tx.execute(txn->{var rows=lock(c);if(rows.isEmpty())return false;var j=rows.get(0);var d=rows.get(1);if(!identity(j,d)||attempts(d)!=1||d.get("request_hash")==null||!Set.of("SUBMITTING","ACCEPTED","UNKNOWN").contains(d.get("stage"))||d.get("provider_message_id")!=null&&!sid.equals(d.get("provider_message_id")))throw rule();String state=Set.of("delivered","read").contains(status)?"DELIVERED":Set.of("failed","undelivered","canceled").contains(status)?"FAILED":"SENT";Timestamp due=Timestamp.from(clock.instant().plusSeconds(30));jdbc.update("UPDATE integration.notification_job SET state=?,provider_reference=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",state,sid,due,now(),c.id());jdbc.update("UPDATE integration.notification_dispatch SET stage=?,provider_message_id=?,error_code=NULL,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='staff-reply-worker' WHERE id=?",state.equals("FAILED")?"FAILED":"ACCEPTED",sid,due,now(),c.id());jdbc.update("INSERT INTO integration.notification_attempt(id,created_by,job_id,attempt_number,provider,provider_message_id,result,duration_ms,channel) VALUES (?,'staff-reply-worker',?,1,'TWILIO',?,?,?,'WHATSAPP') ON CONFLICT (job_id,attempt_number) DO NOTHING",EventCodec.uuid7(clock.instant()),c.id(),sid,state,duration);evidence(c.id(),c.correlation(),state);return true;}));}
 public boolean beforeWriteFailed(Claim c){return unknown(c,"PROVIDER_OUTCOME_UNKNOWN");}
 private void evidence(UUID id,UUID correlation,String state){audit.append("staff-reply-worker",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.RECONCILIATION,null,Map.of("state",state,"channel","WHATSAPP"),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.messaging.staff_reply.dispatch","state",state).increment();}});}
 private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
}
